    ('d7b40000-0000-5000-8000-000000000033'::uuid, 'd7b20000-0000-5000-8000-000000000005'::uuid, 'Babaannesine göre toprakta solucan olması neyi gösterir?', 1, 1, 2, 'Selin solucanı görünce babaannesi sevinir ve toprakta solucan varsa toprağın sağlıklı olduğunu söyler.',
     'Toprağın iyi durumda olduğunu', 'Toprağın çok kuru olduğunu', 'Fidelerin hastalandığını', 'Toprağa fide dikilemeyeceğini', 'A', 0),
    ('d7b40000-0000-5000-8000-000000000034'::uuid, 'd7b20000-0000-5000-8000-000000000005'::uuid, 'Solucanların açtığı tüneller toprağa ne sağlar?', 1, 1, 2, 'İkinci paragrafa göre bu tünellerden toprağa hava ve su girer, bitki kökleri de bu yollardan kolay ilerler.',
     'Toprağın sertleşmesini', 'Hava ve suyun girmesini', 'Yaprakların çürümesini', 'Güneşin içeri girmesini', 'B', 1),
    ('d7b40000-0000-5000-8000-000000000035'::uuid, 'd7b20000-0000-5000-8000-000000000005'::uuid, 'Solucanların bıraktığı küçük toprak yığınları neden değerlidir?', 1, 2, 2, 'Üçüncü paragrafta bu yığınların bitkiler için çok değerli bir besin kaynağı olduğu anlatılır.',
