    ('d7b40000-0000-5000-8000-000000000241'::uuid, 'd7b20000-0000-5000-8000-000000000033'::uuid, 'Zeynep okuyacağı şehre nasıl gitti?', 1, 1, 1, 'İlk paragrafa göre Zeynep eylül sonunda otobüse biner ve yolculuk dokuz saat sürer.',
