    ('d7b40000-0000-5000-8000-000000000242'::uuid, 'd7b20000-0000-5000-8000-000000000033'::uuid, 'Zeynep durakta neden zor duruma düştü?', 1, 1, 1, 'Zeynep daha önce hiç tramvaya binmemiştir; makinedeki düğmelerden hangisine basacağını anlamaz ve arkasında kuyruk oluşur.',
