    ('d7b40000-0000-5000-8000-000000000246'::uuid, 'd7b20000-0000-5000-8000-000000000033'::uuid, 'Hafta sonu tramvayın son durağında ne vardı?', 1, 1, 1, 'Onuncu paragrafa göre Zeynep ile Selin son durağa gider; orada büyük bir göl vardır ve kenarında yürürler.',
     'Eski bir kale', 'Geniş bir park', 'Büyük bir göl', 'Bir kitapçı', 'C', 5),
    ('d7b40000-0000-5000-8000-000000000247'::uuid, 'd7b20000-0000-5000-8000-000000000033'::uuid, 'Yerini yaşlı adama verirken Zeynep''in ilk günü hatırlaması neyi düşündürür?', 2, 4, 1, 'Zeynep ilk gün kendisine yardım eden kadını düşünür; artık şehre alışmış ve iyiliği başkasına yapan taraf olmuştur.',
