    ('d7b40000-0000-5000-8000-000000000270'::uuid, 'd7b20000-0000-5000-8000-000000000036'::uuid, 'Elif neden geride kalmıştı?', 1, 2, 2, 'Altıncı paragrafa göre Elif kurtarma yeleğini çıkarmak için iskelenin yanında geride kalmıştır.',
